            values.removeAt(2)
        }
    }
    fun placedCoins(edges:Array<IntArray>,cost:IntArray):LongArray{
        val n=cost.size;
        val graph=Array(n){
            mutableListOf<Int>()
        };
        for(edge in edges){
            graph[edge[0]].add(edge[1]);
            graph[edge[1]].add(edge[0])
        };
        val parent=IntArray(n){
            -1
        };
        val order=IntArray(n);
        parent[0]=0;
        val stack=java.util.ArrayDeque<Int>();
        stack.addLast(0);
        var orderSize=0;
        while(stack.isNotEmpty()){
            val node=stack.removeLast();
            order[orderSize++]=node;
            for(next in graph[node])if(parent[next]==-1){
                parent[next]=node;
                stack.addLast(next)
            }
        };
        val subtreeSize=IntArray(n){
            1
        };
        val extremes=Array(n){
            LongArray(0)
        };
        val answer=LongArray(n);
        for(index in n-1 downTo 0){
            val node=order[index];
            val values=mutableListOf<Long>();
            addExtreme(values,cost[node].toLong());
            for(next in graph[node])if(parent[next]==node){
                subtreeSize[node]+=subtreeSize[next];
                for(value in extremes[next])addExtreme(values,value)
            };
            values.sort();
            extremes[node]=values.toLongArray();
            if(subtreeSize[node]<3)answer[node]=1 else{
                val last=values.lastIndex;
                val largest=values[last]*values[last-1]*values[last-2];
                val mixed=values[0]*values[1]*values[last];
                answer[node]=maxOf(0L,largest,mixed)
            }
        };
        return answer
    }
}

